"""Plain-text summaries of orders."""


def _report(orders, keep):
    rows = [order for order in orders if keep(order)]
    lines = ['%-12s %3d x %7.2f = %9.2f' % (o['name'].strip().title(), o['qty'], o['price'], o['qty'] * o['price'])
             for o in rows]
    lines.append('TOTAL %.1f' % sum(o['qty'] * o['price'] for o in rows))
    return '\n'.join(lines)


def paid_report(orders):
    return _report(orders, lambda o: o['status'] == 'paid')


def unpaid_report(orders):
    return _report(orders, lambda o: o['status'] != 'paid')


def all_report(orders):
    return _report(orders, lambda o: True)
